<?php
declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';
ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Lax');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_name('tehran_courier');session_start();date_default_timezone_set('Asia/Tehran');header('Cache-Control:no-store,private,max-age=0');header('X-Robots-Tag:noindex,nofollow');
if(!file_exists(__DIR__.'/config.php')){http_response_code(503);exit('سرویس آماده نیست.');}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/sms_lib.php';}catch(Throwable $e){ts_log_internal($e,'SYS-101');ts_html_fail('SYS-101',503,'index.php');}
if(isset($_GET['t'])){$t=trim((string)$_GET['t']);if(preg_match('/^[a-f0-9]{32,64}$/',$t)){$st=$pdo->prepare('SELECT id FROM couriers WHERE access_token=? AND active=1 LIMIT 1');$st->execute([$t]);$id=(int)($st->fetchColumn()?:0);if($id){session_regenerate_id(true);$_SESSION['courier_id']=$id;$_SESSION['courier_last']=time();header('Location:courier.php',true,303);exit;}}http_response_code(403);exit('لینک ورود پیک معتبر نیست.');}
$cid=(int)($_SESSION['courier_id']??0);if(!$cid||time()-(int)($_SESSION['courier_last']??0)>43200){$_SESSION=[];session_destroy();http_response_code(403);exit('نشست پیک منقضی شده؛ لینک ورود را دوباره باز کنید.');}$_SESSION['courier_last']=time();$st=$pdo->prepare('SELECT * FROM couriers WHERE id=? AND active=1');$st->execute([$cid]);$courier=$st->fetch();if(!$courier){session_destroy();exit('حساب پیک غیرفعال است.');}$pdo->prepare('UPDATE couriers SET last_seen_at=NOW() WHERE id=?')->execute([$cid]);
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}$oid=max(0,(int)($_POST['order_id']??0));$a=(string)($_POST['action']??'');try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT status FROM orders WHERE id=? AND courier_id=? FOR UPDATE');$st->execute([$oid,$cid]);$status=(string)($st->fetchColumn()?:'');if($status==='')throw new RuntimeException('سفارش برای شما نیست.');if($a==='out'&&in_array($status,['ready','out'],true)){$pdo->prepare("UPDATE orders SET status='out',status_updated_at=NOW() WHERE id=?")->execute([$oid]);ts_sms_order_event($pdo,$oid,'out');$msg='سفارش در مسیر ثبت شد.';}elseif($a==='delivered'&&$status==='out'){$pdo->prepare("UPDATE orders SET status='delivered',delivered_at=NOW(),status_updated_at=NOW() WHERE id=?")->execute([$oid]);$pdo->prepare('UPDATE order_items SET picked=1,picked_at=COALESCE(picked_at,NOW()) WHERE order_id=?')->execute([$oid]);ts_sms_order_event($pdo,$oid,'delivered');$msg='تحویل سفارش ثبت شد.';}else throw new RuntimeException('این تغییر وضعیت مجاز نیست.');$pdo->commit();ts_process_sms_queue($pdo,3);}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$err=ts_error_text('SYS-100');ts_log_internal($x,'SYS-100');}}
$st=$pdo->prepare("SELECT o.*,c.name customer_name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.courier_id=? AND o.status IN ('ready','out') ORDER BY FIELD(o.status,'out','ready'),o.id");$st->execute([$cid]);$orders=$st->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><title>پنل پیک | طهران</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:650px;margin:15px auto;padding:0 10px}.job{background:#fff;border:1px solid #e5ece6;border-radius:18px;padding:15px;margin:12px 0}.address{background:#f5f8f5;border-radius:12px;padding:10px;margin:10px 0;line-height:1.8}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.actions button{width:100%;min-height:48px}.phone{font-size:18px;font-weight:800}</style></head><body><header class="top"><div class="brand"><span class="logo">🛵</span><span><b><?=e($courier['name'])?></b><small>پنل پیک سوپرمارکت طهران</small></span></div></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><?php if(!$orders):?><div class="panel">فعلاً سفارشی برای شما نیست.</div><?php endif;?><?php foreach($orders as $o):?><article class="job"><h2>سفارش #<?=(int)$o['id']?> · <?=$o['status']==='out'?'در مسیر':'آماده تحویل'?></h2><div><b><?=e($o['customer_name'])?></b> · <a class="phone" href="tel:<?=e($o['phone'])?>"><?=e($o['phone'])?></a></div><div class="address"><?=e($o['address'])?><?php if($o['delivery_zone_name']):?><br><span class="muted"><?=e($o['delivery_zone_name'])?></span><?php endif;?><?php if($o['delivery_lat']!==null&&$o['delivery_lng']!==null):?><br><a class="btn" style="display:inline-block;margin-top:8px" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&amp;query=<?=rawurlencode((string)$o['delivery_lat'].','.(string)$o['delivery_lng'])?>">🧭 مسیریابی تا مشتری</a><?php endif;?></div><div><b><?=number_format((int)$o['total'])?> تومان</b> · پرداخت <?=e($o['payment_status']==='paid'?'شده':'در محل')?></div><div class="actions" style="margin-top:12px"><?php if($o['status']==='ready'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="out"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><button class="btn">🚚 تحویل گرفتم</button></form><?php else:?><div></div><?php endif;?><?php if($o['status']==='out'):?><form method="post" onsubmit="return confirm('تحویل مشتری شد؟')"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="delivered"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><button class="btn">✅ تحویل شد</button></form><?php endif;?></div></article><?php endforeach;?></main></body></html>
